INSERT INTO legal_references (title, citation, source, source_url, category, summary, keywords, jurisdiction, effective_date, verified)
VALUES
  ('Bharatiya Nyaya Sanhita, 2023', 'BNS 2023', 'india_code', 'https://www.indiacode.nic.in/', 'criminal', 'The BNS replaces the Indian Penal Code. It codifies substantive criminal law, defining offences and punishments across 358 sections.', ARRAY['criminal','bns','offences','punishment'], 'India', '2024-07-01', true),
  ('Bharatiya Nagarik Suraksha Sanhita, 2023', 'BNSS 2023', 'india_code', 'https://www.indiacode.nic.in/', 'criminal', 'The BNSS replaces the Code of Criminal Procedure 1973. It governs criminal procedure including arrest, investigation, trial, and appeals.', ARRAY['criminal','bnss','procedure','trial'], 'India', '2024-07-01', true),
  ('Bharatiya Sakshya Adhiniyam, 2023', 'BSA 2023', 'india_code', 'https://www.indiacode.nic.in/', 'criminal', 'The BSA replaces the Indian Evidence Act 1872. It governs the admissibility and evaluation of evidence in courts.', ARRAY['evidence','bsa','trial'], 'India', '2024-07-01', true),
  ('Constitution of India — Article 21', 'Article 21', 'constitution', 'https://www.constitutionofindia.net/', 'constitutional', 'Article 21 guarantees that no person shall be deprived of his life or personal liberty except according to procedure established by law. The Supreme Court has interpreted this to include the right to a speedy trial and access to justice.', ARRAY['constitution','right to life','liberty','speedy trial','access to justice'], 'India', '1950-01-26', true),
  ('Constitution of India — Article 39A', 'Article 39A', 'constitution', 'https://www.constitutionofindia.net/', 'constitutional', 'Article 39A directs the State to ensure that the legal system promotes justice and provides free legal aid, so that no citizen is denied access to justice by reason of economic or other disabilities.', ARRAY['constitution','legal aid','free legal aid','access to justice'], 'India', '1950-01-26', true),
  ('Constitution of India — Article 22', 'Article 22', 'constitution', 'https://www.constitutionofindia.net/', 'constitutional', 'Article 22 provides protections against arrest and detention, including the right to be informed of grounds of arrest, the right to consult a legal practitioner, and production before a magistrate within 24 hours.', ARRAY['constitution','arrest','detention','rights'], 'India', '1950-01-26', true),
  ('Information Technology Act, 2000', 'IT Act 2000', 'india_code', 'https://www.indiacode.nic.in/', 'cyber', 'The IT Act governs electronic commerce, digital signatures, cybercrime, and electronic records in India. Key offences include data theft, identity fraud, and cyber terrorism under Sections 43, 66, and 66F.', ARRAY['cyber','it act','cybercrime','digital','fraud'], 'India', '2000-10-17', true),
  ('Consumer Protection Act, 2019', 'CPA 2019', 'india_code', 'https://www.indiacode.nic.in/', 'consumer', 'The CPA 2019 protects consumer rights against unfair trade practices, defective goods, and deficient services. It establishes Consumer Disputes Redressal Commissions at district, state, and national levels.', ARRAY['consumer','consumer protection','unfair trade'], 'India', '2020-07-20', true),
  ('Legal Services Authorities Act, 1987', 'LSA Act 1987', 'india_code', 'https://www.indiacode.nic.in/', 'legal aid', 'The LSA Act establishes the framework for free legal aid and services in India. It created NALSA, State Legal Services Authorities, and District Legal Services Authorities to provide free legal services to eligible persons.', ARRAY['legal aid','nalsa','free legal services'], 'India', '1987-10-02', true),
  ('Right to Information Act, 2005', 'RTI Act 2005', 'india_code', 'https://www.indiacode.nic.in/', 'general', 'The RTI Act empowers citizens to request information from public authorities, promoting transparency and accountability in governance.', ARRAY['rti','transparency','information'], 'India', '2005-10-12', true),
  ('Hindu Marriage Act, 1955', 'HMA 1955', 'india_code', 'https://www.indiacode.nic.in/', 'family', 'The HMA governs marriage, divorce, and related matters among Hindus. Grounds for divorce include cruelty, desertion, and irretrievable breakdown.', ARRAY['family','marriage','divorce','hindu'], 'India', '1955-05-18', true),
  ('Code of Civil Procedure, 1908', 'CPC 1908', 'india_code', 'https://www.indiacode.nic.in/', 'civil', 'The CPC governs the procedure for civil litigation in India, including suits, appeals, execution of decrees, and interim relief.', ARRAY['civil','cpc','procedure','suits'], 'India', '1908-01-01', true),
  ('Supreme Court of India — Speedy Trial Jurisprudence', 'Multiple judgments', 'supreme_court', 'https://main.sci.gov.in/', 'constitutional', 'The Supreme Court has repeatedly held that delay in trial violates Article 21. Key cases include Hussainara Khatoon v. State of Bihar (1979) on undertrial prisoners and Common Cause v. Union of India (2016) on case management.', ARRAY['speedy trial','article 21','delay','undertrial'], 'India', '1979-01-01', true),
  ('Cybercrime Reporting — National Cyber Crime Reporting Portal', 'cybercrime.gov.in', 'government', 'https://cybercrime.gov.in/', 'cyber', 'The National Cyber Crime Reporting Portal allows citizens to report cybercrimes including online financial fraud, ransomware, and social media-related crimes. Reports are routed to relevant law enforcement.', ARRAY['cyber','cybercrime','report','fraud','online'], 'India', '2020-01-01', true)
INSERT INTO legal_aid_resources (name, authority_type, state, district, address, phone, email, website, description, services, eligibility, language, verified)
VALUES
  ('National Legal Services Authority (NALSA)', 'national', NULL, NULL, 'NILSA, Supreme Court of India Compound, Tilak Marg, New Delhi - 110001', '011-23383281', 'nalsa-india@nalsa.gov.in', 'https://nalsa.gov.in', 'The apex body for free legal services in India, established under the Legal Services Authorities Act, 1987. NALSA frames policies and monitors legal aid programmes nationwide.', ARRAY['Free legal aid','Legal advice','Lok Adalats','Legal literacy'], 'Eligible persons include women, children, SC/ST, victims of trafficking, mentally ill, disabled, persons in custody, and those with annual income below prescribed limits.', ARRAY['en','hi'], true),
  ('Supreme Court Legal Services Committee', 'national', NULL, NULL, 'Supreme Court of India, Tilak Marg, New Delhi - 110001', '011-23386216', 'sclsc@sci.nic.in', 'https://main.sci.gov.in/services/sclsc', 'Provides free legal aid and services to eligible persons for matters before the Supreme Court of India, including drafting and engaging senior advocates.', ARRAY['Supreme Court legal aid','Senior advocate engagement','Drafting'], 'Persons eligible under Section 12 of LSA Act with cases before the Supreme Court.', ARRAY['en','hi'], true),
  ('Tamil Nadu State Legal Services Authority (TNSLSA)', 'state', 'Tamil Nadu', NULL, 'High Court Buildings, Madras High Court, Chennai - 600104', '044-25300000', 'tamilnaduslsa@gmail.com', 'https://www.tnslsa.in', 'The State Legal Services Authority for Tamil Nadu, providing free legal aid, organising Lok Adalats, and running legal literacy programmes across the state.', ARRAY['Free legal aid','Lok Adalat','Mediation','Legal clinics','Paralegal services'], 'Residents of Tamil Nadu eligible under Section 12 of LSA Act.', ARRAY['en','ta'], true),
  ('Chennai District Legal Services Authority', 'district', 'Tamil Nadu', 'Chennai', 'City Civil Court Complex, Egmore, Chennai - 600008', '044-28413376', 'chennaidlsa@gmail.com', 'https://www.tnslsa.in', 'District-level legal services authority providing free legal aid, pre-litigation counselling, mediation, and Lok Adalats for Chennai district residents.', ARRAY['Free legal aid','Mediation','Lok Adalat','Pre-litigation counselling'], 'Residents of Chennai district meeting LSA Act eligibility criteria.', ARRAY['en','ta'], true),
  ('Madurai District Legal Services Authority', 'district', 'Tamil Nadu', 'Madurai', 'District Court Complex, Madurai - 625001', '0452-2521234', 'maduraidlsa@gmail.com', 'https://www.tnslsa.in', 'District-level legal services authority serving Madurai district, offering free legal representation, mediation, and legal awareness camps.', ARRAY['Free legal aid','Mediation','Lok Adalat','Legal awareness'], 'Residents of Madurai district meeting LSA Act eligibility criteria.', ARRAY['en','ta'], true),
  ('Legal Aid Clinic — Tamil Nadu Bar Council', 'clinic', 'Tamil Nadu', NULL, 'Madras High Court, Chennai - 600104', '044-25341523', NULL, 'https://www.tnbarcouncil.org', 'A legal aid clinic run in association with the Tamil Nadu Bar Council offering basic legal consultation and referral services for citizens.', ARRAY['Legal consultation','Referral','Basic advice'], 'Open to all citizens seeking initial legal guidance.', ARRAY['en','ta'], true),
  ('Coimbatore District Legal Services Authority', 'district', 'Tamil Nadu', 'Coimbatore', 'District Court Complex, Coimbatore - 641018', '0422-2456789', 'coimbatoredlsa@gmail.com', 'https://www.tnslsa.in', 'District legal services authority for Coimbatore providing free legal aid, mediation, and Lok Adalat services.', ARRAY['Free legal aid','Mediation','Lok Adalat'], 'Residents of Coimbatore district meeting LSA Act eligibility criteria.', ARRAY['en','ta'], true),
  ('National Cyber Crime Reporting Portal', 'ngo', NULL, NULL, 'Ministry of Home Affairs, Government of India', '1930 (Helpline)', 'cybercrime-helpline@ncpr.gov.in', 'https://cybercrime.gov.in', 'A government portal for reporting cyber crimes including online financial fraud, ransomware, and social media offences. Cases are routed to state law enforcement.', ARRAY['Cybercrime reporting','Financial fraud complaint','Helpline'], 'Open to all citizens facing cybercrime.', ARRAY['en','hi','ta'], true)
